def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    for i in range(n):
        if history[i][1] == 'D':
            opp_d += 1

    d_c = 0
    d_d = 0
    c_c = 0
    c_d = 0
    hard = 0
    for i in range(n - 1):
        a = history[i][0]
        next_b = history[i + 1][1]
        if a == 'C':
            if next_b == 'C':
                c_c += 1
            else:
                c_d += 1
        else:
            if next_b == 'C':
                d_c += 1
            else:
                d_d += 1
            if i + 2 < n and history[i + 1][0] == 'C' and history[i + 2][1] == 'D':
                hard += 1

    r = 10 if n >= 10 else n
    start = n - r
    rec_opp_d = 0
    for i in range(start, n):
        if history[i][1] == 'D':
            rec_opp_d += 1

    last_my, last_opp = history[-1]
    prev_my = history[-2][0] if n >= 2 else 'C'

    rate_d = opp_d / float(n)
    d_test = d_c + d_d
    c_test = c_c + c_d
    if d_test > 0:
        pD = (d_c + 0.5) / (d_test + 1.0)
    else:
        pD = 0.5
    if c_test > 0:
        pC = (c_c + 0.5) / (c_test + 1.0)
    else:
        pC = 1.0 - rate_d

    exploitable = False

    if (hard == 0 and d_test >= 1 and d_c > d_d and d_d == 0 and
            rate_d <= 0.25 and n >= 12 and c_c >= max(4, n // 4)):
        exploitable = True

    if d_test >= 2:
        if d_c > d_d and rate_d <= 0.45:
            exploitable = True
        if pD >= 0.70 and rate_d <= 0.40:
            exploitable = True
        if (d_test >= 2 and c_test >= 2 and abs(pD - pC) <= 0.12 and
                rate_d <= 0.55):
            exploitable = True

    if hard >= 2 and d_d > 0:
        exploitable = False

    if exploitable:
        if last_opp == 'D':
            if rec_opp_d <= 2 and hard == 0:
                return 'C'
            return 'D'
        return 'D'

    if rate_d >= 0.65:
        return 'D'

    hard_reactor = hard >= 1 and d_d >= d_c and rec_opp_d >= 2

    if last_opp == 'D':
        if prev_my == 'D' or last_my == 'D':
            if hard_reactor and rec_opp_d >= 4:
                return 'D'
            return 'C'

        if n >= 96 and rate_d <= 0.12 and rec_opp_d <= 1 and hard == 0:
            return 'C'

        if rec_opp_d >= 3:
            return 'D'

        return 'D'

    if last_my == 'D':
        if hard_reactor:
            return 'D'
        return 'C'

    if opp_d > 0 and rate_d <= 0.25 and rec_opp_d <= 1 and hard == 0:
        if n >= 70 and rng.random() < 0.04:
            return 'D'
        if n >= 85 and rng.random() < 0.06:
            return 'D'

    return 'C'
